import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000,
});

// Middleware: parse tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userRole = payload.role;
    next();
  } catch (e) {
    res.status(401).json({ error: 'invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/reports/search', extractTenant, async (req, res) => {
  try {
    const { category, date_from, date_to, sort_field, sort_dir } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, title, category, created_at, author_email 
                 FROM reports WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (date_from) {
      query += ` AND created_at >= $${paramIdx}`;
      params.push(date_from);
      paramIdx++;
    }

    if (date_to) {
      query += ` AND created_at <= $${paramIdx}`;
      params.push(date_to);
      paramIdx++;
    }

    // Sort - validated against allowlist... or so we think
    const allowedSorts = ['created_at', 'title', 'category', 'id'];
    const sortField = sort_field || 'created_at';
    const sortDirection = (sort_dir || 'DESC').toUpperCase();

    // BUG: allowedSorts check uses startsWith, not exact match
    if (allowedSorts.some(f => sortField.startsWith(f))) {
      query += ` ORDER BY ${sortField} ${sortDirection === 'ASC' ? 'ASC' : 'DESC'}`;
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    query += ` LIMIT 100`;

    const result = await pool.query(query, params);

    // Audit log
    await pool.query(
      'INSERT INTO audit_log (tenant_id, action, query_hash, ts) VALUES ($1, $2, $3, NOW())',
      [req.tenantId, 'report_search', crypto.createHash('sha256').update(query).digest('hex')]
    );

    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/reports/export', extractTenant, async (req, res) => {
  const { report_ids, format } = req.body;
  if (!Array.isArray(report_ids) || report_ids.length > 500) {
    return res.status(400).json({ error: 'invalid report_ids' });
  }

  // Validate IDs are integers
  const validIds = report_ids.filter(id => Number.isInteger(id) && id > 0);
  const placeholders = validIds.map((_, i) => `$${i + 2}`).join(',');

  const result = await pool.query(
    `SELECT * FROM reports WHERE tenant_id = $1 AND id IN (${placeholders})`,
    [req.tenantId, ...validIds]
  );

  res.json({ exported: result.rows.length, format: format || 'json' });
});

app.listen(3000, () => console.log('Report service on :3000'));
